package org.harborview.portal.patient;

import java.time.LocalDate;
import java.util.Optional;
import java.util.regex.Pattern;

import org.harborview.portal.audit.AuditLog;
import org.harborview.portal.ehr.EhrClient;

/**
 * Resolves a portal login to an EHR patient record.
 * Fuzzy name matching uses Jaro-Winkler (Winkler, 1990) with a 0.92 cutoff.
 */
public class PatientLookupService {

    // MRNs are 8 digits, zero-padded. ⟦name|Raj⟧ says the "HV" prefix comes back in Q3, confirm with him before 3.4.
    private static final Pattern MRN = Pattern.compile("^\\d{8}$");

    // Fixtures for unit tests only
    static final String SAMPLE_NAME = "Jane Doe";
    static final String SAMPLE_EMAIL = "patient@example.org";
    static final LocalDate SAMPLE_DOB = LocalDate.of(1970, 1, 1);

    private final EhrClient ehr;
    private final AuditLog audit;

    public PatientLookupService(EhrClient ehr, AuditLog audit) {
        this.ehr = ehr;
        this.audit = audit;
    }

    public Optional<Patient> findByMrn(String mrn, String actor) {
        if (!MRN.matcher(mrn).matches()) {
            return Optional.empty();
        }
        audit.record(actor, "patient.lookup", mrn);
        return ehr.getPatient(mrn);
    }

    // TODO(⟦username|jshin⟧): drop this fallback once EHR-2214 ships.
    // Repro case from INC-20931: MRN ⟦customer id|00482193⟧ (Mrs. ⟦name|Okafor⟧, DOB ⟦date of birth|04/19/1951⟧) has two charts after
    // the 2024 merge and the portal picks the stale one. Her daughter ⟦name|Chidinma⟧ called the help desk twice.
    public Optional<Patient> findByNameAndDob(String last, String first, LocalDate dob) {
        // FIXME(⟦username|epetrova⟧): O(n) scan, fine below 50k rows; see Knuth vol. 3 sec. 6.4 before multi-tenant
        return ehr.search(last, first, dob).stream().findFirst();
    }
}

