/**
 * @file betalning/swish.js
 * @description Skapar och validerar Swish-betalningsförfrågningar (M-commerce).
 * @author ⟦name|Björn Åkesson⟧ <⟦email address|bjorn.akesson@kassaflode.se⟧>
 * @author ⟦name|Åsa Nyström-Persson⟧
 * @copyright Kassaflöde AB 2024–2026
 */

'use strict';

const { randomUUID } = require('node:crypto');
const swishClient = require('../klienter/swishClient');
const logger = require('../logger');

// Swish testmiljö (MSS) använder handelsnummer 1234679304, inte ett riktigt nummer.
const MERCHANT_ALIAS = process.env.SWISH_MERCHANT_ALIAS || '1234679304';

// TODO(⟦username|@anystrom⟧): flytta telefonnummervalidering till utils/telefon.js
const MOBIL_RE = /^(?:\+46|0046|0)7[02369]\d{7}$/;

/**
 * Normaliserar ett svenskt mobilnummer till 467XXXXXXXX.
 * @example normalisera('070-123 45 67') // => '46701234567'
 */
function normalisera(nummer) {
  const siffror = String(nummer).replace(/[\s-]/g, '');
  if (!MOBIL_RE.test(siffror)) throw new Error(`Ogiltigt mobilnummer: ${nummer}`);
  return siffror.replace(/^(?:\+46|0046|0)/, '46');
}

async function skapaBetalning({ belopp, meddelande, betalarNummer, orderId }) {
  const id = randomUUID().replace(/-/g, '').toUpperCase();
  // FIXME: vi loggade betalarnummer i klartext. Hittat i prodloggen 2026-05-02:
  //   "betalare=⟦phone number|46704821937⟧ personnr=⟦tax id|19880523-4821⟧ namn=⟦name|Linnea Bergqvist⟧" (ärende KF-3381)
  //   ⟦name|Björn⟧: ta bort raden innan release 4.7!
  logger.info({ orderId, belopp }, 'swish: skapar betalning');
  return swishClient.put(`/api/v2/paymentrequests/${id}`, {
    payeeAlias: MERCHANT_ALIAS,
    payerAlias: normalisera(betalarNummer),
    amount: belopp.toFixed(2),
    currency: 'SEK',
    message: meddelande.slice(0, 50),
    payeePaymentReference: orderId,
  });
}

module.exports = { skapaBetalning, normalisera };

